package com.sprintboard;

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;

/** Server-side standalone review, usable without an open browser or frontend runtime. */
@Service
public class SprintDigestSnapshot {
 private final WorkspaceService workspace;
 public SprintDigestSnapshot(WorkspaceService workspace){this.workspace=workspace;}
 public record Snapshot(String sprintId,String name,int number,String summary,String html,List<Map<String,Object>> blocks){
  public Snapshot(String sprintId,String name,int number,String summary,String html){this(sprintId,name,number,summary,html,List.of(Map.of("type","section","text",Map.of("type","plain_text","text",summary))));}
 }
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public Snapshot build(String requested,Instant now){
  String id=requested;
  if(id==null||id.isBlank()){
   var active=workspace.sprints().stream().filter(s->"active".equals(s.get("status"))).toList();
   if(active.isEmpty())return null;
   if(active.size()!=1)throw new IllegalArgumentException("Birden fazla aktif sprint var; günlük gönderim yapılmadı.");
   id=active.getFirst().get("id").toString();
  }
  var sprint=workspace.sprint(id);if(sprint==null)throw new IllegalArgumentException("Sprint bulunamadı.");
  return render(sprint,workspace.capacity(id),workspace.reviewTeam(id),workspace.settings(),workspace.overtime(),workspace.overtimeEntries(),now);
 }
 @SuppressWarnings("unchecked") static List<Map<String,Object>> rows(Map<String,Object> m,String key){return (List<Map<String,Object>>)m.getOrDefault(key,List.of());}
 static String s(Map<String,Object> m,String key){return Objects.toString(m.get(key),"");}
 static double n(Map<String,Object> m,String key){return DefectReserve.number(m,key);}
 static String h(Object value){return Objects.toString(value,"").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
 static String num(double x){return String.format(Locale.forLanguageTag("tr-TR"),"%.1f",x).replaceAll(",0$","");}
 static String status(Map<String,Object> t){return BauPolicy.isBau(t)?"done":s(t,"status");}
 static String label(String key){return switch(key){case "done"->"Done";case "doing"->"Devam ediyor";case "undone"->"Undone";default->"Yapılacak";};}
 static boolean leave(Map<String,Object> t){return "LEAVE".equals(t.get("workKind"))||"LEAVE".equals(t.get("taskSubtype"));}
 static String kind(Map<String,Object> t){return "DEFECT".equals(t.get("taskCategory"))?s(t,"taskSubtype").replace('_',' '):s(t,"taskCategory");}
 static String metric(String label,double value,String unit){return "<div class='metric'><span>"+h(label)+"</span><strong>"+num(value)+" <small>"+unit+"</small></strong></div>";}
 static String bar(String name,long done,long total){double p=total==0?0:100.0*done/total;return "<div class='bar'><div><b>"+h(name)+"</b><span>"+done+" / "+total+" Done</span></div><div class='track'><i style='width:"+String.format(Locale.ROOT,"%.2f",p)+"%'></i></div></div>";}
 static Snapshot render(Map<String,Object> sprint,List<Map<String,Object>> capacity,List<Map<String,Object>> team,Map<String,Object> settings,List<Map<String,Object>> history,List<Map<String,Object>> entries,Instant now){
  String id=s(sprint,"id"),name=s(sprint,"name"),time=DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm").withZone(ZoneId.of("Europe/Istanbul")).format(now);
  int number=(int)n(sprint,"number");var tasks=rows(sprint,"items");var delivery=tasks.stream().filter(t->!BauPolicy.isBau(t)).toList();long done=delivery.stream().filter(t->"done".equals(status(t))).count();
  double coreCapacity=capacity.stream().filter(c->!Boolean.TRUE.equals(c.get("supportMember"))).mapToDouble(c->n(c,"availableHours")).sum();
  double corePlan=capacity.stream().filter(c->!Boolean.TRUE.equals(c.get("supportMember"))).mapToDouble(c->n(c,"plannedHours")).sum();
  var support=capacity.stream().filter(c->Boolean.TRUE.equals(c.get("supportMember"))).toList();double supportPlan=support.stream().mapToDouble(c->n(c,"plannedHours")).sum();
  var overtime=entries.stream().filter(e->id.equals(e.get("sprintId"))).toList();double actual=history.stream().filter(e->n(e,"sprintNumber")==number).mapToDouble(e->n(e,"earnedHours")).sum()+overtime.stream().mapToDouble(e->n(e,"earnedHours")).sum();
  double planned=0,matched=0,remaining=0,excess=0,unplanned=0,classified=0;
  for(var e:overtime){double p=n(e,"plannedHours"),a=n(e,"planActualHours");if(p>0||a>0){planned+=p;matched+=Math.min(p,a);remaining+=Math.max(0,p-a);excess+=Math.max(0,a-p);}if("UNPLANNED".equals(e.get("planClassification")))unplanned+=n(e,"earnedHours");if(Set.of("PLANNED","UNPLANNED").contains(s(e,"planClassification")))classified+=n(e,"earnedHours");}
  var summary=new StringBuilder(h(name)+" · "+time+" (Türkiye)\nTeslimat: "+done+" / "+delivery.size()+" Done (BAU hariç)\nÇekirdek kapasite / plan: "+num(coreCapacity)+" / "+num(corePlan)+" sa · Dış Support planı: "+num(supportPlan)+" sa\nMesai: "+num(actual)+" sa gerçekleşen · "+num(planned)+" sa planlanan\n");
  var out=new StringBuilder("<!doctype html><html lang='tr'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta http-equiv='Content-Security-Policy' content=\"default-src 'none'; style-src 'unsafe-inline'; img-src data:; base-uri 'none'; form-action 'none'\"><title>"+h(name)+" · Sprint Review</title><style>");
  out.append("*{box-sizing:border-box}body{margin:0;background:#edf2f6;color:#18384a;font:15px/1.55 system-ui,sans-serif}main{max-width:1160px;margin:30px auto;background:#fcfaf6;padding:48px}header{border-bottom:4px solid #147d72;padding-bottom:24px}h1{font:700 40px Georgia,serif;margin:12px 0}h2{font:700 26px Georgia,serif;margin:8px 0 22px}h3{margin:0 0 12px;font-size:17px}.eyebrow{text-transform:uppercase;font-size:12px;letter-spacing:2px;color:#147d72;font-weight:800}.muted,small{color:#627788}.section{margin-top:32px;padding-top:26px;border-top:1px solid #cbd7de}.metrics,.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.metrics{grid-template-columns:repeat(auto-fit,minmax(180px,1fr));margin:20px 0}.metric{border:1px solid #d5e1e6;padding:18px;border-radius:12px;background:#fff}.metric span,.metric strong{display:block}.metric strong{font-size:30px}.metric small{font-size:14px}.bar{margin:18px 0}.bar>div:first-child{display:flex;justify-content:space-between;gap:12px}.track{height:14px;background:#d9e3ea;border-radius:8px;overflow:hidden;margin-top:8px}.track i{display:block;height:100%;background:#13937b}.counts{display:flex;flex-wrap:wrap;gap:10px}.pill{padding:5px 10px;border-radius:8px;background:#e9eef3;display:inline-block;font-size:13px}.done{background:#d8f2e8}.doing{background:#dce7ff}.undone{background:#fee3e3}.task{background:#fff;border:1px solid #d5e1e6;border-radius:10px;padding:17px;margin:12px 0;break-inside:avoid;overflow-wrap:anywhere}.task h3{margin:7px 0}.people{display:flex;gap:14px;flex-wrap:wrap}.person{display:flex;align-items:center;gap:10px;padding:12px;background:#eef3f5;border-radius:10px}.person img{width:80px;height:80px;flex:none;object-fit:cover;border-radius:50%}.person{min-width:0;max-width:100%;break-inside:avoid}.person>div{min-width:0;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #dae2e7}th{background:#edf3f2}footer{padding-top:25px;color:#627788;font-size:13px}@media(max-width:700px){.personal-table thead{display:none}.personal-table tr{display:block;padding:10px 0;border-bottom:1px solid #dae2e7}.personal-table th,.personal-table td{display:block;border:0;padding:6px 10px}.personal-table td:before{content:attr(data-label) ': ';font-weight:600}main{margin:0;padding:22px}.grid{grid-template-columns:1fr}h1{font-size:30px}}@media print{body{background:white}main{margin:0;padding:15px;max-width:none}.section{break-inside:avoid}h2{break-after:avoid}}");
  out.append("</style></head><body><main><header><span class='eyebrow'>"+h(settings.get("teamName"))+" · Sprint Review</span><h1>"+h(name)+"</h1><p>"+h(sprint.get("goal"))+"</p><p>"+h(sprint.get("start"))+" — "+h(sprint.get("end"))+" · "+h(sprint.get("status"))+"</p><small>"+time+" · Europe/Istanbul · Gönderim anındaki kayıtlı durum</small></header>");
  out.append("<section class='section'><span class='eyebrow'>SPRINT EKİBİ</span><h2>Çekirdek ekip & Architecture</h2><div class='people'>");
  for(var member:team){out.append("<div class='person'>");String photo=s(member,"photoDataUrl");if(photo.length()<500_000&&photo.matches("data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+"))out.append("<img alt='' src='"+photo+"'>");out.append("<div><b>"+h(member.get("name"))+"</b><br><small>"+h(member.get("title"))+"</small></div></div>");}out.append("</div></section>");
  out.append("<section class='section'><span class='eyebrow'>TESLİMAT İŞLERİ · BAU HARİÇ</span><h2>Sonuç dağılımı</h2>"+bar("Tamamlanma",done,delivery.size())+"<div class='counts'>");for(String st:List.of("done","doing","todo","undone")){long count=delivery.stream().filter(t->st.equals(status(t))).count();out.append("<span class='pill "+st+"'>"+label(st)+" · "+count+"</span>");}out.append("</div></section>");
  out.append("<section class='section'><h2>İş tipi dağılımı</h2>");var kinds=new TreeSet<String>();for(var t:tasks)kinds.add(kind(t));for(String k:kinds){var group=tasks.stream().filter(t->k.equals(kind(t))).toList();out.append(bar(k,group.stream().filter(t->"done".equals(status(t))).count(),group.size()));}out.append("<small>BAU otomatik Done kabul edilir; teslimat oranına dahil edilmez.</small></section>");
  out.append("<section class='section'><span class='eyebrow'>GÖRELİ TAHMİN · BAU HARİÇ</span><h2>"+("POINTS_AND_HOURS".equals(settings.get("estimationMode"))?"Story point":"Size")+" dağılımı</h2><div class='counts'>");var estimates=new TreeMap<String,Integer>();for(var t:delivery){String estimate="POINTS_AND_HOURS".equals(settings.get("estimationMode"))?(t.get("storyPoints")==null?"SP yok":t.get("storyPoints")+" SP"):s(t,"size");estimates.merge(estimate.isBlank()?"Size yok":estimate,1,Integer::sum);}estimates.forEach((k,v)->out.append("<span class='pill'>"+h(k)+" · "+v+" iş</span>"));out.append("</div></section>");
  out.append("<section class='section'><h2>Çekirdek ekip kapasitesi ve plan</h2><div class='metrics'>"+metric("Kullanılabilir kapasite",coreCapacity,"sa")+metric("Çekirdek ekip planı",corePlan,"sa")+"</div><small>Kapasite, onaylı izinler ve çalışılmayan günler düşülmüş; kapasiteye dahil planlı mesai eklenmiş değerdir. Gerçekleşen mesai ikinci kez eklenmez.</small></section>");
  out.append("<section class='section'><span class='eyebrow'>YALNIZ BU SPRINT</span><h2>Mesai</h2><div class='metrics'>"+metric("Gerçekleşen",actual,"sa")+metric("Planlanan",planned,"sa")+metric("Plan içinde gerçekleşen",matched,"sa")+metric("Kalan plan",remaining,"sa")+metric("Planı aşan",excess,"sa")+metric("Plansız",unplanned,"sa")+metric("Eski / sınıflandırılmamış",Math.max(0,actual-classified),"sa")+"</div><small>Mesai ayrı gösterilir; görev eforuna tekrar eklenmez. Hakediş bakiyeleri paylaşılmaz.</small></section>");
  out.append(SlackDigestPresentation.overtimePeople(number,id,history,entries));
  out.append(SlackDigestPresentation.leaves(capacity));
  out.append("<section class='section'><span class='eyebrow'>EKİBE SAĞLANAN DESTEK</span><h2>Dış Support / Architecture</h2><div class='metrics'>"+metric("Atanan destek eforu",supportPlan,"sa")+"</div><table><tr><th>Kişi</th><th>Planlanan</th><th>X destek</th></tr>");for(var c:support){long x=tasks.stream().filter(t->!leave(t)).flatMap(t->DefectReserve.assignments(t).stream()).filter(a->Objects.equals(c.get("memberId"),a.get("memberId"))&&Boolean.TRUE.equals(a.get("supportOnly"))).count();if(n(c,"plannedHours")>0||x>0)out.append("<tr><td>"+h(c.get("memberName"))+"</td><td>"+num(n(c,"plannedHours"))+" sa</td><td>"+x+" atama</td></tr>");}out.append("</table><small>Defect Support rezervinden ayrıdır. X destek saat toplamına eklenmez.</small></section>");
  out.append("<section class='section'><h2>Defect çözüm durumu</h2>");for(String type:List.of("TEST_DEFECT","PROD_DEFECT")){var group=tasks.stream().filter(t->"DEFECT".equals(t.get("taskCategory"))&&type.equals(t.get("taskSubtype"))).toList();long resolved=group.stream().filter(t->"done".equals(status(t))).count();out.append(bar(type.replace('_',' '),resolved,group.size()));summary.append(type.replace('_',' ')+": "+resolved+" çözülen / "+(group.size()-resolved)+" açık\n");var reserved=group.stream().filter(t->!s(t,"reserveTaskId").isBlank()).toList();out.append("<p>Defect Support kapsamında: "+reserved.size()+" iş · "+reserved.stream().filter(t->"done".equals(status(t))).count()+" Done</p>");}out.append("</section>");
  out.append("<section class='section'><span class='eyebrow'>GÜNCEL GÖREVLER</span><h2>Done ve açık işler</h2><div class='grid'>");for(boolean completed:List.of(true,false)){out.append("<div><h3>"+(completed?"Done":"Devam eden / açık")+"</h3>");for(var t:tasks){if(leave(t)||"DEFECT".equals(t.get("taskCategory"))||completed!="done".equals(status(t)))continue;out.append("<article class='task'><span class='pill "+h(status(t))+"'>"+label(status(t))+"</span> <span class='eyebrow'>"+h(kind(t))+"</span><h3>"+h(t.get("name"))+"</h3>");if(Boolean.TRUE.equals(t.get("emergency")))out.append("<span class='pill undone'>Acil / plansız</span>");out.append("<p>"+num(t.containsKey("planningHours")?n(t,"planningHours"):n(t,"estimatedHours"))+" sa plan</p><small>");var names=new ArrayList<String>();for(var a:DefectReserve.assignments(t))names.add(h(a.get("memberName"))+" · "+(Boolean.TRUE.equals(a.get("supportOnly"))?"X destek":num(DefectReserve.planned(a))+" sa"));out.append(String.join(" · ",names)+"</small></article>");}out.append("</div>");}out.append("</div><small>İzin nedenleri, hakediş bakiyeleri ve defect açıklamaları paylaşılmaz. Defectler yukarıda sayısal özetlenir.</small></section><footer>VIBE Craft · "+time+" · Bu dosya sonraki değişikliklerle güncellenmez.</footer></main></body></html>");
  summary.append("Güncel görevler ve dağılımlar ekteki Review HTML dosyasında.");
  return new Snapshot(id,name,number,summary.toString(),out.toString(),SlackDigestPresentation.blocks(name,time,delivery,done,coreCapacity,corePlan,supportPlan,actual,planned));
 }
}
